def parse_int_safe(raw):
    try:
        return int(str(raw).strip()), None
    except (TypeError, ValueError):
        return None, "not a whole number: " + repr(raw)


def parse_all(raws):
    values = []
    problems = []
    for raw in raws:
        value, reason = parse_int_safe(raw)
        if reason is None:
            values.append(value)
        else:
            problems.append(reason)
    return values, problems


